<?php declare(strict_types=1);

namespace App\GraphQL\Queries;

use App\GraphQL\Support\AuthorizesAdmin;
use App\Models\Order;
use Nodesol\LaraQL\Attributes\Query;

/**
 * The order list shown in the admin panel, scoped to the caller's role.
 *
 *   seller              only orders containing at least one of their products,
 *                       and only the lines of their own products
 *   manager / support   every order
 *   super admin         every order
 *
 * The raw `orders` collection generated by LaraQL stays administrator-only
 * (`order.view-all`), so this resolver is the single door into order data that
 * every staff role can safely use.
 */
#[Query(
    name: 'ManageOrders',
    query: '@field(resolver:"ManageOrders") @guard @permission(require: ["order.view"])',
    filters: [
        'status: String',
        'search: String',
        'page: Int',
        'first: Int! = 50',
    ],
    return_type: 'OrderPaginator!',
)]
class ManageOrders
{
    use AuthorizesAdmin;

    /** @param array{} $args */
    public function __invoke($root, array $args)
    {
        $user = $this->requireAdmin();
        $search = trim((string) ($args['search'] ?? ''));

        $query = Order::query()
            ->with(['user'])
            // Only the lines a seller actually sells: the customer's other
            // items belong to other sellers and are none of their business.
            ->with(['items' => function ($items) use ($user): void {
                if ($user->isSeller()) {
                    $items->whereHas(
                        'product',
                        fn ($product) => $product->where('seller_id', $user->id)
                    );
                }
            }])
            ->when(
                $user->isSeller(),
                fn ($builder) => $builder->whereHas(
                    'items.product',
                    fn ($product) => $product->where('seller_id', $user->id)
                )
            )
            ->when(
                ! empty($args['status']),
                fn ($builder) => $builder->where('status', $args['status'])
            )
            ->when($search !== '', function ($builder) use ($search): void {
                $term = '%'.strtolower($search).'%';

                $builder->where(function ($nested) use ($term): void {
                    $nested->whereRaw('lower(coalesce(name, \'\')) like ?', [$term])
                        ->orWhereRaw('lower(coalesce(email, \'\')) like ?', [$term])
                        ->orWhereRaw('lower(coalesce(phone, \'\')) like ?', [$term]);
                });
            })
            ->latest();

        return $query->paginate(
            perPage: (int) ($args['first'] ?? 50),
            page: isset($args['page']) ? (int) $args['page'] : null,
        );
    }
}
